/*
 * CampsiteRatingController.kt
 * Purpose: Entrant rating eligibility and submission for US 01.13.01.
 * Only completed, active reservations belonging to the entrant qualify.
 * Updating the same stay uses the same reservation identifier.
 * Persistence repeats these checks against the saved reservation.
 */
package com.example.code.controller

import com.example.code.data.CampsiteRatingStore
import com.example.code.model.Reservation

/** Returns completed stays at this campsite, newest first, including already rated stays. */
fun rateableStays(
    reservations: List<Reservation>,
    campsiteId: String,
    entrantId: String,
    now: Long,
): List<Reservation> = reservations.filter {
    campsiteId.isNotBlank() && entrantId.isNotBlank() && it.id.isNotBlank() &&
            it.campsiteId == campsiteId && it.entrantId == entrantId &&
            it.status == Reservation.STATUS_ACTIVE && it.endDate > 0 &&
            it.startDate <= it.endDate && it.endDate < now
}.distinctBy { it.id }.sortedWith(compareByDescending<Reservation> { it.endDate }.thenBy { it.id })

/** Shared by the UI controller and the transaction's authoritative reservation check. */
internal fun validateStayRating(
    reservation: Reservation,
    campsiteId: String,
    entrantId: String,
    score: Int,
    now: Long,
) {
    require(score in 1..5) { "Choose a rating from 1 to 5." }
    require(rateableStays(listOf(reservation), campsiteId, entrantId, now).isNotEmpty()) {
        "Only your completed stays at this campsite can be rated."
    }
}

/** Validates a selection before requesting an atomic rating upsert. */
class CampsiteRatingController(
    private val repository: CampsiteRatingStore,
    private val clock: () -> Long = System::currentTimeMillis,
) {
    suspend fun submit(campsiteId: String, entrantId: String, stay: Reservation, score: Int) {
        validateStayRating(stay, campsiteId, entrantId, score, clock())
        repository.saveRating(campsiteId, stay.id, entrantId, score)
    }
}
